#!/usr/bin/env node
// Writes packages/kit-core/src/page-engine/engine-source.ts: the engine as a string constant,
// so the reader package can inject it into an iframe/WebView document. Metro cannot import
// raw text, hence the generated file; a test asserts it matches engine.js.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..', 'packages', 'kit-core');
const src = readFileSync(join(pkg, 'page-engine', 'engine.js'), 'utf8');
const out = `// GENERATED by scripts/gen-engine-source.mjs from page-engine/engine.js — do not edit.\nexport const ENGINE_SOURCE = ${JSON.stringify(src)};\n`;
writeFileSync(join(pkg, 'src', 'page-engine', 'engine-source.ts'), out);
console.log(`wrote engine-source.ts (${src.length} chars)`);
